/**
 * THE PRESS, AT WORK.

 * One basket press painted through its job: empty, the bag of mash loaded, the
 * plate screwed down with liquid starting to run, the cake pressed hard, and the
 * plate raised with the cake left in the basket. PressRoom plays these in order
 * when you press, so the step that turns a moromi into soy sauce is something
 * you watch rather than a number that changes. Keyed off magenta.
 */
export type PressFrame = 'empty' | 'loaded' | 'pressing' | 'pressed' | 'cake';
export const PRESS_FRAMES: Record<PressFrame, { w: number; h: number; src: string }> = {
  empty: { w: 268, h: 470, src: 'data:image/webp;base64,' },
  loaded: { w: 269, h: 470, src: 'data:image/webp;base64,' },
  pressing: { w: 269, h: 467, src: 'data:image/webp;base64,' },
  pressed: { w: 268, h: 470, src: 'data:image/webp;base64,' },
  cake: { w: 268, h: 469, src: 'data:image/webp;base64,' },
};
